-- Corte 2026-09-08
with c as (
  insert into public.cargas (zona_id, archivo, marcas, resumen, fecha_corte)
  values ((select id from public.zonas where nombre = 'Norte'), 'Levantamiento_Demo_2026-09-08.xlsx', array['Honor', 'Samsung', 'Apple', 'Xiaomi', 'Motorola', 'Oppo', 'Vivo', 'Infinix', 'ZTE', 'Huawei'], '{"exhibiciones":"36/36","muebles_dc":"36/36","muebles_dz":"27/36","promotores":"36/36"}'::jsonb, '2026-09-08')
  on conflict (zona_id, fecha_corte) do nothing
  returning id
)
insert into public.mediciones (carga_id, tienda_codigo, metrica, marca, valor, fecha)
select c.id, v.codigo, v.metrica, v.marca, v.valor, v.fecha::date from c, (values
