with c as (
  insert into public.cargas (zona_id, archivo, marcas, resumen, fecha_corte)
  values ((select id from public.zonas where nombre = 'Norte'), 'Levantamiento_Demo_2026-10-06.xlsx', array['Honor', 'Samsung', 'Apple', 'Xiaomi', 'Motorola', 'Oppo', 'Vivo', 'Infinix', 'ZTE', 'Huawei'], '{"exhibiciones":"35/36","muebles_dc":"35/36","muebles_dz":"26/36","promotores":"35/36"}'::jsonb, '2026-10-06')
  on conflict (zona_id, fecha_corte) do nothing
  returning id
)
